/**
 * Night access — temporary closure + access codes.
 *
 * The site closes every night 10pm-6am IST until Dec 5, 2026 (when the free
 * Appwrite reads reset). During closed hours, two ways in:
 *  - Admins (moderator/founder) via the admin-bypass API route.
 *  - A temporary access code, generated by the assistant and verified
 *    against the `night_access_codes` Appwrite collection.
 *
 * Both set a signed bypass cookie (`ea_night_access`) that the middleware
 * verifies with HMAC-SHA256. The signing secret is the server-only
 * Appwrite API key (already a high-entropy server secret); it is never
 * exposed to the browser. Cookies expire at 6am (end of that night) at
 * the latest.
 */

export const NIGHT_ACCESS_COOKIE = "ea_night_access";

/** Reopen date: Dec 5, 2026 00:00 IST (= Dec 4, 2026 18:30 UTC). */
export const CLOSED_UNTIL_MS = Date.UTC(2026, 11, 4, 18, 30, 0);

const CLOSED_START_HOUR_IST = 22;
const CLOSED_END_HOUR_IST = 6;

/** IST hour (0-23) for a given instant. */
export function istHour(now: Date): number {
  const ist = new Date(now.getTime() + 5.5 * 60 * 60 * 1000);
  return ist.getUTCHours();
}

/**
 * True while the nightly closure applies: before Dec 5, 2026 AND the IST
 * time is between 10pm and 6am. After Dec 5 the site stays open all night.
 */
export function isNightClosed(now: Date): boolean {
  if (now.getTime() >= CLOSED_UNTIL_MS) return false;
  const hour = istHour(now);
  return hour >= CLOSED_START_HOUR_IST || hour < CLOSED_END_HOUR_IST;
}

/** IST timestamp of the next 6am (end of the current closed night). */
export function nextSixAmIstMs(now: Date): number {
  const ist = new Date(now.getTime() + 5.5 * 60 * 60 * 1000);
  const y = ist.getUTCFullYear();
  const m = ist.getUTCMonth();
  const d = ist.getUTCDate();
  const h = ist.getUTCHours();
  // If it is already past 6am IST, the next 6am is tomorrow.
  const day = h >= CLOSED_END_HOUR_IST ? d + 1 : d;
  // 06:00 IST = 00:30 UTC.
  return Date.UTC(y, m, day, 0, 30, 0);
}

function base64urlEncode(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function base64urlDecode(s: string): Uint8Array {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
  const padded = b64 + "=".repeat((4 - (b64.length % 4)) % 4);
  const bin = atob(padded);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Copy bytes into a fresh ArrayBuffer (WebCrypto wants a plain ArrayBuffer). */
function toArrayBuffer(u8: Uint8Array): ArrayBuffer {
  const out = new Uint8Array(u8.length);
  out.set(u8);
  return out.buffer as ArrayBuffer;
}

async function hmacKey(): Promise<CryptoKey> {
  const secret = process.env.APPWRITE_API_KEY || "";
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );
  return keyMaterial;
}

/** Create a signed bypass token expiring at `expiresAtMs` (epoch ms). */
export async function signNightAccess(expiresAtMs: number): Promise<string> {
  const payload = base64urlEncode(
    new TextEncoder().encode(JSON.stringify({ exp: expiresAtMs, kind: "night" })),
  );
  const key = await hmacKey();
  const sig = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(payload),
  );
  return `${payload}.${base64urlEncode(new Uint8Array(sig))}`;
}

/**
 * Verify a bypass token. Returns the expiry (epoch ms) when the signature
 * is valid and the token has not expired, otherwise null.
 */
export async function verifyNightAccess(
  token: string,
): Promise<number | null> {
  try {
    const [payload, sig] = token.split(".");
    if (!payload || !sig) return null;
    const key = await hmacKey();
    const ok = await crypto.subtle.verify(
      "HMAC",
      key,
      toArrayBuffer(base64urlDecode(sig)),
      new TextEncoder().encode(payload),
    );
    if (!ok) return null;
    const data = JSON.parse(
      new TextDecoder().decode(base64urlDecode(payload)),
    ) as { exp?: unknown; kind?: unknown };
    if (data.kind !== "night") return null;
    if (typeof data.exp !== "number") return null;
    if (data.exp <= Date.now()) return null;
    return data.exp;
  } catch {
    return null;
  }
}

/** Best-effort client IP from proxy headers (Cloudflare / Vercel). */
export function getClientIp(headers: Headers): string {
  const cf = headers.get("cf-connecting-ip");
  if (cf) return cf.trim();
  const xff = headers.get("x-forwarded-for");
  if (xff) return xff.split(",")[0].trim();
  const xr = headers.get("x-real-ip");
  if (xr) return xr.trim();
  return "unknown";
}
